var app=new Vue({el:"#app",delimiters:["[[","]]"],data:{errors:[],coments:[]},methods:{getData(){const a=window.location.origin+"/dashboard/comments/data";axios.get(a).then(a=>{this.coments=a.data}).catch(a=>{console.log(a)})},addNewQues(){const a=window.location.origin+"/dashboard/comments";axios.post(a).then(a=>{this.coments=a.data}).catch(a=>{console.log(a)})},deleteQues(a,b){const c=window.location.origin+"/dashboard/comments/"+b;axios.delete(c).then(b=>{this.coments.splice(a,1),this.$notify({group:"notification",type:b.data.status,title:b.data.title,text:b.data.message,duration:2500,speed:1e3})}).catch(a=>{console.log(a)})},updateData(a){const b=window.location.origin+"/dashboard/comments/"+this.coments[a].id;axios.post(b,{data:this.coments[a].value}).then(a=>{this.$notify({group:"notification",type:a.data.status,title:a.data.title,text:a.data.message,duration:2500,speed:1e3})}).catch(a=>{console.log(a)})}},created(){this.getData()}});